+namespace sv_72e512657c88438ba60636e39b48246a.Services;
+
+/// <summary>
+/// Scoped service that polls for low-stock alerts and notifies all subscribers.
+/// Scoped lifetime ensures each circuit (user) gets an independent instance.
+/// </summary>
+public sealed class InventoryAlertService : IDisposable
+{
+    private readonly Random _random = new();
+    private PeriodicTimer? _timer;
+    private CancellationTokenSource? _cts;
+    private string _warehouseId = WarehouseInfo.Default.Id;
+
+    public int CurrentAlertCount { get; private set; }
+
+    public event Action? OnChange;
+
+    /// <summary>
+    /// Simulates a database query returning the number of items below minimum stock levels.
+    /// </summary>
+    public Task<int> GetLowStockCountAsync(string warehouseId)
+    {
+        return Task.FromResult(_random.Next(0, 16));
+    }
+
+    public void SetWarehouse(string warehouseId)
+    {
+        _warehouseId = warehouseId;
+        CurrentAlertCount = 0;
+        OnChange?.Invoke();
+    }
+
+    public void StartPolling()
+    {
+        StopPolling();
+        _cts = new CancellationTokenSource();
+        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
+        _ = PollLoopAsync(_cts.Token);
+    }
+
+    public void StopPolling()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+        _timer?.Dispose();
+        _timer = null;
+    }
+
+    private async Task PollLoopAsync(CancellationToken ct)
+    {
+        // Fire immediately on start, then every 10 seconds.
+        await FetchAndNotifyAsync();
+
+        while (!ct.IsCancellationRequested)
+        {
+            try
+            {
+                if (!await _timer!.WaitForNextTickAsync(ct))
+                    break;
+            }
+            catch (OperationCanceledException)
+            {
+                break;
+            }
+
+            await FetchAndNotifyAsync();
+        }
+    }
+
+    private async Task FetchAndNotifyAsync()
+    {
+        CurrentAlertCount = await GetLowStockCountAsync(_warehouseId);
+        OnChange?.Invoke();
+    }
+
+    public void Dispose()
+    {
+        StopPolling();
+    }
+}
+

