@* Interactive dropdown for warehouse selection.
   Rendered inside the static MainLayout but given its own render mode
   so it can handle change events. Updates the CascadingValueSource
   so every [CascadingParameter] subscriber re-renders automatically. *@

@rendermode InteractiveServer
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@inject InventoryAlertService AlertService
@using sv_72e512657c88438ba60636e39b48246a.Services

<select class="form-select form-select-sm" style="width:auto;"
        value="@_selectedId" @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseInfo.All)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private string _selectedId = WarehouseInfo.Default.Id;

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? WarehouseInfo.Default.Id;
        var selected = WarehouseInfo.All.FirstOrDefault(w => w.Id == _selectedId)
                       ?? WarehouseInfo.Default;

        // Notify all [CascadingParameter] subscribers across render modes.
        await WarehouseSource.NotifyChangedAsync(selected);

        // Update the alert service so polling uses the new warehouse.
        AlertService.SetWarehouse(selected.Id);
    }
}

@* Alert badge that subscribes to InventoryAlertService changes.
   Uses InvokeAsync because the event can fire from a background polling thread. *@

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_72e512657c88438ba60636e39b48246a.Services

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable
@using sv_72e512657c88438ba60636e39b48246a.Services

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(_alertCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(_alertCount > 5 ? "text-danger" : "text-success")">
                    @_alertCount
                </p>
                <p class="text-muted">
                    Items below minimum level at <strong>@_warehouse.Name</strong>
                </p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private WarehouseInfo _warehouse = WarehouseInfo.Default;
    private int _alertCount;
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(() =>
        {
            _alertCount = AlertService.CurrentAlertCount;
            StateHasChanged();
        });
        AlertService.OnChange += _handler;

        // Start polling when the dashboard becomes visible.
        AlertService.StartPolling();
    }

    protected override void OnParametersSet()
    {
        if (Warehouse is not null)
        {
            _warehouse = Warehouse;
        }
        _alertCount = AlertService.CurrentAlertCount;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        // Stop polling when the user navigates away.
        AlertService.StopPolling();
    }
}

